        "Marc Feldmann",
        "Ravinder N. Maini"
      ],
      "assessment": {
        "nobel_worthiness": "TNF blockade transformed rheumatoid arthritis and established a broadly influential therapeutic principle for inflammatory disease.",
        "attribution": "Feldmann and Maini provide a focused and persuasive attribution for the mechanistic rationale and clinical translation.",
        "maturity": "The benefit, limitations, and wide clinical consequences of TNF inhibition have been established over decades.",
        "uncertainties": [
          "The discovery-to-therapy pathway involved substantial contributions beyond the two proposed laureates."
        ]
      }
    },
